const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (near Banamepe along the Digul River; approximate)
    const pt = ee.Geometry.Point([139.60, -6.10]);
    const geom = pt.buffer(15000).bounds(); // ~15 km buffer box
    const areaKm2 = ee.Number(geom.area()).divide(1e6);

    // 2. Data Acquisition
    const gfc = ee.Image('UMD/hansen/global_forest_change_2023_v1.11');
    const tc = gfc.select('treecover2000');
    const loss = gfc.select('lossyear');
    const gain = gfc.select('gain');

    // Forest definition
    const tcThresh = 30;
    const forest2000 = tc.gte(tcThresh);

    // End of 2002: remove loss up to and including 2002 (lossyear 1..2)
    const lostBy2002 = loss.gt(0).and(loss.lte(2));
    const forest2002 = forest2000.and(lostBy2002.not());

    // End of 2019: remove loss up to and including 2019 (lossyear 1..19), include gains not lost by 2019
    const lostBy2019 = loss.gt(0).and(loss.lte(19));
    const forest2019_base = forest2000.and(lostBy2019.not());
    const forest2019_gain = gain.eq(1).and(lostBy2019.not());
    const forest2019 = forest2019_base.or(forest2019_gain);

    // Valid mask: use treecover band presence
    const validMask = tc.mask(); // where data exists

    // Build bands for one-pass reduction
    const ones = ee.Image(1);
    const pix_valid = ones.updateMask(validMask).rename('pix_valid');
    const pix_f02 = ones.updateMask(forest2002).rename('pix_f02');
    const pix_f19 = ones.updateMask(forest2019).rename('pix_f19');
    const area_valid = ee.Image.pixelArea().divide(10000).updateMask(validMask).rename('area_valid_ha');
    const area_f02 = ee.Image.pixelArea().divide(10000).updateMask(forest2002).rename('area_f02_ha');
    const area_f19 = ee.Image.pixelArea().divide(10000).updateMask(forest2019).rename('area_f19_ha');

    const combined = ee.Image.cat([pix_valid, pix_f02, pix_f19, area_valid, area_f02, area_f19]);

    const sums = combined.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e10
    });

    const out = sums.getInfo();
    const validPix = out ? out.pix_valid : null;
    const f02Pix = out ? out.pix_f02 : null;
    const f19Pix = out ? out.pix_f19 : null;
    const validAreaHa = out ? out.area_valid_ha : null;
    const f02AreaHa = out ? out.area_f02_ha : null;
    const f19AreaHa = out ? out.area_f19_ha : null;

    // 3. Validation
    const areaKm2Val = areaKm2.getInfo();
    if (!out || validPix === null || validAreaHa === null) {
      console.log('Calculation failed: null results.');
      console.log('C3');
      return;
    }
    if (validPix === 0 || validAreaHa === 0) {
      console.log('No valid pixels in region after masking.');
      console.log('C2');
      return;
    }
    if (f02AreaHa === null || f19AreaHa === null || isNaN(f02AreaHa) || isNaN(f19AreaHa)) {
      console.log('Calculation failed: forest area is null/NaN.');
      console.log('C3');
      return;
    }

    // 4. Stats and Decision
    const deltaHa = f19AreaHa - f02AreaHa;
    const tolHa = Math.max(0.01 * validAreaHa, 10); // tolerance: 1% of valid area or 10 ha
    const decreased = deltaHa < -tolHa;

    // 5. Evidence prints (<=20 lines)
    console.log('Region area (km2):', areaKm2Val.toFixed(1));
    console.log('Valid pixels (~1km):', Math.round(validPix));
    console.log('Treecover threshold (%):', tcThresh);
    console.log('Forest 2002 (ha):', f02AreaHa.toFixed(1), 'pixels:', Math.round(f02Pix || 0));
    console.log('Forest 2019 (ha):', f19AreaHa.toFixed(1), 'pixels:', Math.round(f19Pix || 0));
    console.log('Change 2019-2002 (ha):', deltaHa.toFixed(1));
    console.log('Tolerance (ha):', tolHa.toFixed(1));

    // Final tag
    console.log(decreased ? 'A' : 'B');
  } catch (err) {
    console.log('Error:', String(err).slice(0, 120));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
